import { Component, OnInit } from '@angular/core';
import { Router, RouterLink } from '@angular/router';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { NotesService, Note } from '../../services/notes.service';
import { NoteEditorComponent } from '../note-editor/note-editor.component';

@Component({
  selector: 'app-notes-list',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink, NoteEditorComponent],
  templateUrl: './notes-list.component.html',
  styleUrls: ['./notes-list.component.scss']
})
export class NotesListComponent implements OnInit {
  notes: Note[] = [];
  filtered: Note[] = [];
  query = '';
  showCreate = false;

  constructor(private notesService: NotesService, private router: Router) {}

  ngOnInit(): void {
    this.load();
  }

  load() {
    this.notesService.listNotes().subscribe(list => {
      this.notes = list;
      this.applyFilter();
    });
  }

  applyFilter() {
    const q = this.query.toLowerCase().trim();
    this.filtered = !q ? this.notes : this.notes.filter(n =>
      n.title.toLowerCase().includes(q) || n.content.toLowerCase().includes(q)
    );
  }

  open(note: Note) {
    this.router.navigate(['/note', note.id]);
  }

  onCreated(note: Note) {
    this.showCreate = false;
    this.notes.unshift(note);
    this.applyFilter();
  }
}
<div class="row">
  <aside class="card list" aria-label="Notes list">
    <div class="toolbar">
      <input
        class="input"
        type="search"
        [(ngModel)]="query"
        (input)="applyFilter()"
        placeholder="Search notes..."
        aria-label="Search notes"
      />
      <button class="btn" (click)="showCreate = !showCreate" [attr.aria-expanded]="showCreate" aria-controls="create-area">
        + New note
      </button>
    </div>

    <ul class="items" role="listbox" aria-label="Available notes">
      <li
        *ngFor="let n of filtered"
        tabindex="0"
        (keydown.enter)="open(n)"
        (click)="open(n)"
        role="option"
        class="item"
        [attr.aria-label]="'Open note ' + n.title"
      >
        <div class="title">{{ n.title || 'Untitled' }}</div>
        <div class="meta">{{ n.updatedAt | date:'short' }}</div>
      </li>
      <li *ngIf="filtered.length === 0" class="empty">No notes match your search.</li>
    </ul>
  </aside>

  <section class="card detail">
    <div id="create-area" *ngIf="showCreate" class="create-area">
      <h2>Create note</h2>
      <app-note-editor (saved)="onCreated($event)" (cancel)="showCreate=false"></app-note-editor>
    </div>
    <div *ngIf="!showCreate" class="placeholder">
      <p>Select a note from the list or create a new one.</p>
    </div>
  </section>
</div>
